"""生成可直接双击打开的轻量版；复杂的中文分词与词云请使用 Streamlit 完整版。"""
import json
from collections import Counter
from pathlib import Path
from core import load_records
from taxonomy import TAXONOMY, STOCK_LENSES

root=Path(__file__).parent
records,meta=load_records(root/'answers.md')
fields=('id','title','url','date','body','length','category','subcategory','classification_method','tags')
short=[{k:r[k] for k in fields} for r in records]
lexicon=sorted({term for v in TAXONOMY.values() for words in v.values() for term in words if len(term)>1},key=len, reverse=True)
# 离线版统计已定义主题词项的命中次数，不冒充中文切词词频。
count={w:sum((r['title']+' '+r['body']).lower().count(w.lower()) for r in records) for w in lexicon}
count=dict(sorted(((k,v) for k,v in count.items() if v>0),key=lambda x:x[1], reverse=True)[:150])
ideas={
"普通人参与市场的风险":"作者多次提醒普通投资者注意亏损风险及自身能力边界。",
"成交量与牛熊判断":"作者多次将市场总成交量作为行情判断依据，对指数和常规指标持怀疑态度。",
"情绪影响与交易纪律":"作者强调追涨杀跌与情绪诱导的风险，重视执行预设计划。",
"操纵、主力与筹码":"作者常从资金、主力和筹码角度解释市场；相关具体指控未独立核实。",
"买卖时机与仓位":"作者提出过尾盘买卖、提前挂单和随成交量调整仓位的个人方法。",
"学习、独立思考与交易技术":"作者更强调独立思考和亲自验证交易逻辑，质疑照搬技术指标。",
"价值投资与长期持有":"存在谨慎甚至批判价值投资的表述，也曾谈及长期买入银行股，应结合原文理解。"}

index={"records":short,"topics":STOCK_LENSES,"ideas":ideas,"termCounts":count,"meta":meta}
serialized=json.dumps(index, ensure_ascii=False, separators=(',',':')).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026').replace('\u2028','\\u2028').replace('\u2029','\\u2029')
html=r'''<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/>
<title>知乎内容研究台 · 离线版</title>
<style>
:root{font-family:Inter,"Microsoft YaHei","PingFang SC",sans-serif;color:#162234;background:#f5f7fb}*{box-sizing:border-box}body{margin:0}button,input,select{font:inherit}button{cursor:pointer}
.layout{display:grid;grid-template-columns:255px minmax(0,1fr);min-height:100vh}.sidebar{position:sticky;top:0;height:100vh;padding:28px 20px;background:#102238;color:#dfe8f8}.brand{font-size:21px;font-weight:800;letter-spacing:.3px;margin:0 0 6px}.slogan{color:#a1b5cf;font-size:12px;margin-bottom:35px}.navbtn{display:block;text-align:left;width:100%;border:0;background:transparent;color:#c4d2e7;font-size:14px;padding:13px 15px;border-radius:9px;margin:4px 0}.navbtn:hover,.navbtn.active{color:white;background:#29446b}.sidebar-foot{position:absolute;bottom:24px;font-size:12px;line-height:1.9;color:#91a9c5;left:22px;right:20px}.content{padding:32px clamp(20px,4vw,60px);max-width:1600px;width:100%}h1{font-size:27px;letter-spacing:-.6px;margin:0 0 8px}h2{font-size:19px;margin:22px 0 15px}h3{font-size:16px;margin:12px 0}p{line-height:1.8}.muted{color:#76859a}.caption{color:#6d7e93;font-size:12px}.card{background:white;border:1px solid #e8edf4;border-radius:16px;padding:21px;box-shadow:0 2px 8px rgba(17,35,57,.025)}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:24px 0}.metric-num{font-size:29px;font-weight:750;color:#113d75;letter-spacing:-1px}.metric-label{color:#798799;font-size:13px;margin-top:5px}.grid2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.toprow{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}.pill{border-radius:50px;padding:5px 9px;font-size:11px;background:#eef3fc;color:#2d5990;display:inline-block;margin-right:7px}.notice{background:#fff7e9;color:#936519;padding:13px 17px;border-radius:9px;font-size:13px;line-height:1.8;margin:18px 0}.barrow{display:grid;grid-template-columns:110px minmax(70px,1fr) 60px;gap:9px;align-items:center;margin:12px 0;font-size:13px}.bartrack{height:10px;border-radius:8px;background:#e9f0f9;overflow:hidden}.bar{height:100%;background:linear-gradient(90deg,#4f9af7,#1b5ba9);border-radius:8px}.spark{display:flex;align-items:end;gap:4px;height:160px;border-bottom:1px solid #dce4ee}.spark div{min-width:5px;flex:1;background:linear-gradient(180deg,#88b6f4,#1c5caa);border-radius:3px 3px 0 0;position:relative}.spark div:hover{background:#fca65c}.record{margin:12px 0;padding:17px 19px;background:white;border:1px solid #e8edf4;border-radius:13px}.record-head{font-size:15px;font-weight:650;cursor:pointer;line-height:1.6}.record-head:hover{color:#1b65b8}.record-body{display:none;margin-top:16px;border-top:1px solid #e5edf4;padding-top:16px}.record.open .record-body{display:block}.raw{white-space:pre-wrap;word-break:break-word;line-height:1.85;font-size:14px;color:#2c3b4b;max-height:600px;overflow:auto}.meta{color:#718198;font-size:12px;margin:7px 0}.toolbar{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:15px 0}.field{border:1px solid #d6e0ee;background:white;border-radius:9px;min-height:40px;padding:9px 12px;color:#203551;min-width:140px}.search{flex:1;min-width:240px}.action{background:#1b5ca8;border:0;color:white;padding:10px 14px;border-radius:9px;font-size:13px}.action.secondary{background:white;border:1px solid #d1dcea;color:#2d5b94}.action:disabled{opacity:.45;cursor:default}.flex-spacer{flex:1}.insight{padding:16px 18px;border:1px solid #e1e8f2;border-radius:12px;background:white;margin:10px 0;cursor:pointer}.insight:hover,.insight.selected{border-color:#80b2ef;background:#f4f9ff}.tag{display:inline-block;background:#eaf1fa;color:#3670a9;padding:4px 9px;border-radius:20px;font-size:12px;margin:3px}.term{display:inline-block;margin:8px 12px 8px 0;cursor:pointer;color:#154a83;font-weight:600}.term:hover{color:#d67a28}.empty{padding:35px;text-align:center;color:#8ba0b9}a{color:#1669bc;text-decoration:none}a:hover{text-decoration:underline}.link{display:inline-block;margin-top:9px;font-size:13px}.small{font-size:12px}.foot{padding:35px 0;color:#8da0b5;font-size:12px}.hidden{display:none!important}
@media(max-width:900px){.layout{grid-template-columns:1fr}.sidebar{position:static;height:auto;padding:16px}.slogan,.sidebar-foot{display:none}.navbtn{display:inline-block;width:auto;font-size:12px;margin:5px 2px}.content{padding:22px 15px}.metrics{grid-template-columns:repeat(2,1fr)}.grid2{grid-template-columns:1fr}.brand{margin-bottom:8px}} 
</style></head><body><div class="layout"><aside class="sidebar"><div class="brand">◉ 知乎内容研究台</div><div class="slogan">OFFLINE TEXT RESEARCH · 本地版</div>
<button class="navbtn active" data-page="overview">▥　全局概览</button><button class="navbtn" data-page="library">▣　回答资料库</button><button class="navbtn" data-page="topics">◈　专题观点证据</button><button class="navbtn" data-page="words">▤　专题词项统计</button>
<div class="sidebar-foot">3906 条真实回答<br>无需网络，无需安装依赖<br>分析结果为自动归纳，支持回溯原文</div></aside>
<main class="content"><div class="toprow"><div><h1 id="title">回答数据全局概览</h1><div class="muted small">知乎用户「无二小二」 · 来源：2026-10-13 导出文件</div></div><button class="action secondary" id="exportBtn">导出当前筛选 CSV ↓</button></div>
<div id="overview"><div class="metrics" id="metrics"></div><div class="notice">数据质量提示：3906 条回答的赞同数全部为 0；原始 Markdown 未包含作者评论区留言，不能据此判断真实热度。分类包含 1626 个基于弱监督模型给出的待复核建议。</div><div class="grid2"><div class="card"><h3>领域分布 · 主分类</h3><div id="catBars"></div></div><div class="card"><h3>发文数量 · 按月份</h3><div class="spark" id="trend"></div><p class="caption" id="range"></p></div></div><h2>近期回答</h2><div id="latest"></div></div>
<div id="library" class="hidden"><h2>多条件全文检索</h2><div class="toolbar"><input class="field search" id="q" placeholder="检索标题或全文，多个关键词以空格分隔"/><select class="field" id="category"></select><select class="field" id="sort"><option value="new">最新优先</option><option value="old">最早优先</option><option value="long">篇幅由长到短</option><option value="short">篇幅由短到长</option></select></div><div class="meta" id="matchCount"></div><div id="results"></div><div class="toolbar" id="pages"></div></div>
<div id="topics" class="hidden"><h2>专题思想与全部回答证据</h2><div class="notice">以下是基于原文关键词的“观点线索”，匹配到的回答不一定认同该观点；特定市场指控未经独立核实，也不是投资建议。</div><div class="toolbar"><select class="field" id="topicCategory"></select><select class="field" id="lens" style="flex:1"></select></div><div class="grid2"><div class="card"><h3>观点概括与可追溯线索</h3><div id="insights"></div></div><div class="card"><h3>该专题相关回答</h3><div class="metric-num" id="topicCount"></div><p class="caption">下方目录包含该专题全部匹配回答，按 20 条分页。可通过顶部按钮导出当前完整清单。</p><div id="topicCategories"></div></div></div><h2>匹配回答目录 <span id="topicNum" class="caption"></span></h2><div id="topicResults"></div><div class="toolbar" id="topicPages"></div></div>
<div id="words" class="hidden"><h2>关键词项命中频次</h2><div class="notice">离线版统计的是分类词典中的词项命中次数（不是中文分词结果）。如需真正的 Jieba 词频、可下载的 PNG 词云、可编辑停用词和相似度检索，请运行完整 Python 版。</div><div id="wordCloud" class="card"></div><h2>高频词项 TOP 35</h2><div class="card" id="wordList"></div></div>
<div class="foot">本地离线数据浏览器 · 数据不上传任何服务器 · 您可点击问题标题展开完整回答</div></main></div>
<script>
const DATA = /*DATA*/;
const records=DATA.records,TOPICS=DATA.topics,IDEAS=DATA.ideas;
const CATS=[...new Set(records.map(x=>x.category))].sort();
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n).toLocaleString('zh-CN');
const hit=(r,term)=>(r.title+' '+r.body).toLowerCase().includes(term.toLowerCase());
const sorted=(arr,mode)=>arr.slice().sort((a,b)=>mode==='old'?a.date.localeCompare(b.date):mode==='long'?b.length-a.length:mode==='short'?a.length-b.length:b.date.localeCompare(a.date));
const topicLabels=Object.keys(TOPICS);let current='overview',libPage=1,topicPage=1,topicResults=[],libResults=[];
function metric(label,val){return `<div class="card"><div class="metric-num">${esc(val)}</div><div class="metric-label">${esc(label)}</div></div>`}
function renderCard(r){return `<div class="record" id="rec-${esc(r.id)}"><div class="record-head" onclick="this.parentElement.classList.toggle('open')">${esc(r.title)}<span style="float:right;color:#8b9db1">⌄</span></div><div class="meta">${esc(r.date)}　·　${esc(r.category)} / ${esc(r.subcategory)}　·　${fmt(r.length)} 字　·　${esc(r.classification_method)}</div><div class="record-body"><div class="raw">${esc(r.body)}</div><a class="link" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">打开知乎原文 ↗</a></div></div>`}
function bars(items,dom){let max=Math.max(...items.map(x=>x[1]),1);$(dom).innerHTML=items.map(([k,v])=>`<div class="barrow"><span>${esc(k)}</span><div class="bartrack"><div class="bar" style="width:${v/max*100}%"></div></div><b>${fmt(v)}</b></div>`).join('')}
function overview(){let counts={};records.forEach(r=>counts[r.category]=(counts[r.category]||0)+1);let cc=Object.entries(counts).sort((a,b)=>b[1]-a[1]);$('metrics').innerHTML=metric('回答总数',fmt(records.length))+metric('覆盖年份','2018—2026')+metric('自动标注类别',cc.length)+metric('模型建议待复核',fmt(records.filter(r=>r.classification_method.includes('模型')).length));bars(cc,'catBars');let months={};records.forEach(r=>{let m=r.date.slice(0,7);months[m]=(months[m]||0)+1});let sortedM=Object.keys(months).sort();let max=Math.max(...Object.values(months));$('trend').innerHTML=sortedM.map(m=>`<div title="${m} · ${months[m]}条" style="height:${Math.max(3,months[m]/max*100)}%"></div>`).join('');$('range').textContent=`${sortedM[0]} 至 ${sortedM.at(-1)} · 共 ${sortedM.length} 个月有记录`;$('latest').innerHTML=records.slice(0,8).map(renderCard).join('')}
function options(element,items,first){$(element).innerHTML=(first?`<option value="">${first}</option>`:'')+items.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}
function filterLib(){let cat=$('category').value,terms=$('q').value.trim().toLowerCase().split(/\s+/).filter(Boolean);libResults=sorted(records.filter(r=>(!cat||r.tags.includes(cat))&&terms.every(t=>hit(r,t))),$('sort').value);libPage=1;drawLib()}
function pagination(n,page,id,cb){let max=Math.max(1,Math.ceil(n/20));$(id).innerHTML=`<button class="action secondary" id="${id}prev" ${page<=1?'disabled':''}>上一页</button><span>第 ${page} / ${max} 页 · 总 ${fmt(n)} 条</span><button class="action secondary" id="${id}next" ${page>=max?'disabled':''}>下一页</button>`;$(id+'prev').onclick=()=>cb(Math.max(1,page-1));$(id+'next').onclick=()=>cb(Math.min(max,page+1))}
function drawLib(){let start=(libPage-1)*20;$('matchCount').textContent=`匹配 ${fmt(libResults.length)} 条，显示第 ${Math.min(start+1,libResults.length)}—${Math.min(start+20,libResults.length)} 条`;$('results').innerHTML=libResults.slice(start,start+20).map(renderCard).join('')||'<div class="empty">没有符合条件的记录</div>';pagination(libResults.length,libPage,'pages',p=>{libPage=p;drawLib()})}
function selectTopic(){let cat=$('topicCategory').value;if(cat==='股票金融'){$('lens').disabled=false;options('lens',topicLabels,'全部股票金融回答')}else{$('lens').disabled=true;options('lens',[],'该领域全部回答')}$('insights').innerHTML='';if(cat==='股票金融'){let all=records.filter(r=>r.tags.includes(cat));$('insights').innerHTML=topicLabels.map((key,i)=>{let terms=TOPICS[key];let found=all.filter(r=>terms.some(t=>hit(r,t)));return `<div class="insight" onclick="document.getElementById('lens').selectedIndex=${i+1};changeTopic();"><b>${esc(key)}</b><p class="small muted">${esc(IDEAS[key])}</p><span class="tag">${found.length} 条证据线索</span></div>`}).join('')}else{$('insights').innerHTML='<p>该领域提供按分类检索的全部原始回答目录。可阅读高频议题、发布日期和各篇回答，而不是凭少数句子猜测作者的整体立场。</p>'}changeTopic()}
function changeTopic(){let cat=$('topicCategory').value,lens=$('lens').value;topicResults=records.filter(r=>r.tags.includes(cat));if(lens&&TOPICS[lens])topicResults=topicResults.filter(r=>TOPICS[lens].some(t=>hit(r,t)));topicResults=sorted(topicResults,'new');$('topicCount').textContent=fmt(topicResults.length)+' 条';$('topicNum').textContent=' · 共 '+topicResults.length+' 条';let subs={};topicResults.forEach(r=>subs[r.subcategory]=(subs[r.subcategory]||0)+1);bars(Object.entries(subs).sort((a,b)=>b[1]-a[1]).slice(0,7),'topicCategories');topicPage=1;drawTopic()}
function drawTopic(){let start=(topicPage-1)*20;$('topicResults').innerHTML=topicResults.slice(start,start+20).map(renderCard).join('')||'<div class="empty">没有匹配回答</div>';pagination(topicResults.length,topicPage,'topicPages',p=>{topicPage=p;drawTopic()})}
function wordCloud(){let entries=Object.entries(DATA.termCounts).sort((a,b)=>b[1]-a[1]);let max=entries[0][1];$('wordCloud').innerHTML=entries.slice(0,100).map(([w,n])=>`<span class="term" title="${n}次" style="font-size:${12+24*Math.sqrt(n/max)}px" onclick="openSearch('${esc(w)}')">${esc(w)}</span>`).join('');bars(entries.slice(0,35),'wordList')}
function openSearch(s){show('library');$('q').value=s;filterLib()}
function show(p){current=p;['overview','library','topics','words'].forEach(x=>$(x).classList.toggle('hidden',x!==p));document.querySelectorAll('.navbtn').forEach(n=>n.classList.toggle('active',n.dataset.page===p));$('title').textContent=({overview:'回答数据全局概览',library:'原始回答全文资料库',topics:'领域观点与证据整理',words:'文本主题词项分析'})[p]; if(p==='library')filterLib();if(p==='topics')selectTopic();if(p==='words')wordCloud()}
function exportCSV(){let rows=current==='topics'?topicResults:current==='library'?libResults:records;let cols=['id','title','date','category','subcategory','classification_method','length','url','body'];let csv=[cols.join(','),...rows.map(r=>cols.map(k=>{let v=String(r[k]??'');if(/^[=+\-@]/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"'}).join(','))].join('\r\n');let a=document.createElement('a'),blob=new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8'});a.href=URL.createObjectURL(blob);a.download='知乎_'+current+'.csv';a.click();URL.revokeObjectURL(a.href)}
options('category',CATS,'全部领域');options('topicCategory',CATS);$('topicCategory').value='股票金融';$('q').addEventListener('input',filterLib);$('category').addEventListener('change',filterLib);$('sort').addEventListener('change',filterLib);$('topicCategory').addEventListener('change',selectTopic);$('lens').addEventListener('change',changeTopic);$('exportBtn').addEventListener('click',exportCSV);document.querySelectorAll('.navbtn').forEach(n=>n.addEventListener('click',()=>show(n.dataset.page)));overview();show('overview');
</script></body></html>'''
html=html.replace('/*DATA*/',serialized)
(root/'offline_dashboard.html').write_text(html,encoding='utf-8')
print('离线浏览文件:',root/'offline_dashboard.html','bytes:',len(html.encode('utf-8')))
